INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der DHCP-Server für die Verwaltung des IP-Pools verantwortlich?', 2, '[{"text": "Ja", "correct": true, "because": "Server verteilt Adressen"}, {"text": "Nein", "correct": false, "because": "Kernfunktion des Servers"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der IP-Pool in der DHCP-Konfiguration?', 3, '[{"text": "Definiert verfügbare Adressen", "correct": true, "because": "Bereich für Zuweisung"}, {"text": "Bestimmt die Netzwerkgeschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Verschlüsselt Daten", "correct": false, "because": "Nicht DHCP-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Lease-Zeit legt fest, wie lange eine IP gültig ist. b) Der IP-Pool muss öffentlich sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann privat sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der DHCP-Konfiguration?', 4, '[{"text": "IP-Pool", "correct": false, "because": "Definiert Adressbereich"}, {"text": "Lease-Zeit", "correct": false, "because": "Steuert Gültigkeit"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der DHCP-Server die Lease-Zeit festlegt?', 2, '[{"text": "Ja", "correct": true, "because": "Server konfiguriert Dauer"}, {"text": "Nein", "correct": false, "because": "Server-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich sollte im IP-Pool von 192.168.1.0/24 ausgeschlossen werden?', 3, '[{"text": "192.168.1.0", "correct": true, "because": "Netzwerkadresse reserviert"}, {"text": "192.168.1.100", "correct": false, "because": "Nutzbar"}, {"text": "192.168.1.254", "correct": false, "because": "Nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für die DHCP-Konfiguration essenziell?', 5, '[{"text": "Server", "correct": true, "because": "Verwaltet Zuweisung"}, {"text": "IP-Pool", "correct": true, "because": "Liefert Adressen"}, {"text": "Lease-Zeit", "correct": true, "because": "Bestimmt Gültigkeit"}, {"text": "Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein kleiner IP-Pool kann Konflikte verursachen. b) Die Lease-Zeit ist immer 24 Stunden. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist konfigurierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die DHCP-Konfiguration?', 4, '[{"text": "Server", "correct": false, "because": "Verwaltet Prozess"}, {"text": "IP-Pool", "correct": false, "because": "Definiert Adressen"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss der IP-Pool die Netzwerkadresse enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Reserviert, nicht vergeben"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Lease-Zeit wäre für ein temporäres Event sinnvoll?', 4, '[{"text": "1 Stunde", "correct": true, "because": "Kurze Dauer für temporäre Nutzung"}, {"text": "30 Tage", "correct": false, "because": "Zu lang"}, {"text": "1 Jahr", "correct": false, "because": "Übertrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der DHCP-Server keine statischen IPs unterstützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Statische IPs können reserviert werden"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der DHCP-Konfiguration?', 3, '[{"text": "Passender IP-Pool", "correct": true, "because": "Sichert Adressverfügbarkeit"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Server definiert die Lease-Zeit. b) Der IP-Pool muss /32 sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellungen sind für einen DHCP-Server typisch?', 5, '[{"text": "IP-Pool 192.168.1.100-200", "correct": true, "because": "Beispielbereich"}, {"text": "Lease-Zeit 8 Stunden", "correct": true, "because": "Typische Dauer"}, {"text": "Bandbreite 1 Gbps", "correct": false, "because": "Irrelevant"}, {"text": "Protokollverschlüsselung", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der DHCP-Konfiguration unwichtig?', 3, '[{"text": "IP-Pool", "correct": false, "because": "Definiert Adressen"}, {"text": "Lease-Zeit", "correct": false, "because": "Steuert Gültigkeit"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann der IP-Pool 192.168.1.0-255 umfassen?', 3, '[{"text": "Nein", "correct": true, "because": "Netzwerk- und Broadcastadresse ausgeschlossen"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine lange Lease-Zeit den Pool schneller erschöpft?', 2, '[{"text": "Ja", "correct": true, "because": "Adressen länger gebunden"}, {"text": "Nein", "correct": false, "because": "Zeit beeinflusst Verfügbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher IP-Pool passt zu 192.168.1.0/26?', 4, '[{"text": "192.168.1.1-192.168.1.62", "correct": true, "because": "64 Adressen, 2 reserviert"}, {"text": "192.168.1.0-192.168.1.63", "correct": false, "because": "Inkl. Netzwerkadresse"}, {"text": "192.168.1.1-192.168.1.255", "correct": false, "because": "Zu groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Lease-Zeit ist für ein Büro mit festen Geräten sinnvoll?', 3, '[{"text": "7 Tage", "correct": true, "because": "Stabile Zuweisung"}, {"text": "10 Minuten", "correct": false, "because": "Zu kurz"}, {"text": "1 Stunde", "correct": false, "because": "Zu häufige Erneuerung"}]');
